<form method="POST" enctype="multipart/form-data" action="{{ $property->exists ? route('admin.properties.update',$property) : route('admin.properties.store') }}" class="grid gap-6" x-data="{ operation: '{{ old('operation_type', $property->operation_type?->value) }}', rentOperations: @js([\App\Enums\OperationType::Rent->value, \App\Enums\OperationType::SaleRent->value]), price: @js((string) old('price', $property->price)), priceDisplay: '', selectedImages: [], existingImageCount: @js($property->exists ? $property->images->count() : 0), deletedExistingIds: [], imageError: '', init() { this.price = this.cleanPrice(this.price); this.priceDisplay = this.formatPrice(this.price); }, cleanPrice(value) { return String(value || '').replace(/,/g, '').replace(/[^\d.]/g, ''); }, syncPrice(value) { this.priceDisplay = value; this.price = this.cleanPrice(value); }, focusPrice() { this.priceDisplay = this.price; }, blurPrice() { const clean = this.cleanPrice(this.priceDisplay); if (clean === '') { this.price = ''; this.priceDisplay = ''; return; } const number = Number.parseFloat(clean); if (Number.isNaN(number)) { this.price = ''; this.priceDisplay = ''; return; } this.price = number.toFixed(2); this.priceDisplay = this.formatPrice(this.price); }, formatPrice(value) { const clean = this.cleanPrice(value); if (clean === '') { return ''; } const number = Number.parseFloat(clean); if (Number.isNaN(number)) { return ''; } return number.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }, addImages(event) { const incoming = Array.from(event.target.files || []); const available = 10 - (this.existingImageCount - this.deletedExistingIds.length) - this.selectedImages.length; if (incoming.length > available) { this.imageError = 'Sólo puedes seleccionar '+Math.max(available, 0)+' imagen(es) más. El máximo es de 10.'; } else { this.imageError = ''; } incoming.slice(0, Math.max(available, 0)).forEach(file => { const duplicate = this.selectedImages.some(item => item.key === file.name+'-'+file.size+'-'+file.lastModified); if (!duplicate) { this.selectedImages.push({ file, key: file.name+'-'+file.size+'-'+file.lastModified, preview: URL.createObjectURL(file) }); } }); const transfer = new DataTransfer(); this.selectedImages.forEach(item => transfer.items.add(item.file)); this.$refs.imagesInput.files = transfer.files; }, removeImage(index) { URL.revokeObjectURL(this.selectedImages[index].preview); this.selectedImages.splice(index, 1); const transfer = new DataTransfer(); this.selectedImages.forEach(item => transfer.items.add(item.file)); this.$refs.imagesInput.files = transfer.files; this.imageError = ''; } }">@csrf @if($property->exists)@method('PUT')@endif
